```verilog
`timescale 1ns/1ps

module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg  [7:0] in;
    wire [7:0] out;

    // Expected value for checking
    reg  [7:0] expected_out;

    integer errors = 0;
    integer i;

    // 2. Instantiate TopModule dut ( ... );
    TopModule dut (
        .in(in),
        .out(out)
    );

    // Function to compute expected bit reversal
    function [7:0] reverse_bits(input [7:0] val);
        integer idx;
        begin
            for (idx = 0; idx < 8; idx = idx + 1) begin
                reverse_bits[idx] = val[7 - idx];
            end
        end
    endfunction

    // 3. Stimulus & self-checking:
    initial begin
        // Initialize inputs
        in = 8'h00;
        #10;

        // Test specific interesting vectors
        in = 8'hA5; // 10100101 -> expected 10100101
        #10;
        expected_out = reverse_bits(in);
        if (out !== expected_out) begin
            errors = errors + 1;
        end

        in = 8'h01; // 00000001 -> expected 10000000
        #10;
        expected_out = reverse_bits(in);
        if (out !== expected_out) begin
            errors = errors + 1;
        end

        in = 8'h80; // 10000000 -> expected 00000001
        #10;
        expected_out = reverse_bits(in);
        if (out !== expected_out) begin
            errors = errors + 1;
        end

        // Bounded loop for randomized/sequential testing of several vectors
        for (i = 0; i < 10; i = i + 1) begin
            in = $random;
            #10;
            expected_out = reverse_bits(in);
            if (out !== expected_out) begin
                errors = errors + 1;
            end
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
```

